import { readFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '../..');

export const BUNDLE_ORDER = [
    'extension/src/copy.ru.js',
    'extension/src/parser.js',
    'extension/src/metrics.js',
    'extension/src/ui.js',
    'extension/src/related.js',
    'extension/src/searchShard.js',
    'extension/src/content.js',
];

export function stripModuleSyntax(source) {
    return source
        .replace(/^import\s[\s\S]*?from\s+['"][^'"]+['"];?\s*$/gm, '')
        .replace(/^export\s+\{[^}]*\}\s*;?\s*$/gm, '')
        .replace(/^export\s+default\s+/gm, '')
        .replace(/^export\s+(?=async\s+function|function|class|const|let|var)/gm, '');
}

export async function readFirefoxContentBundle(version) {
    const parts = [
        `/* job-xray ${version} content bundle. Generated by scripts/build.mjs. Do not edit. */`,
        ...(await Promise.all(BUNDLE_ORDER.map((rel) => readFile(join(root, rel), 'utf8')))).map(
            stripModuleSyntax,
        ),
    ];
    return parts.join('\n');
}
